insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_112_v1'
from (values
('127.813.d.1.A',3,'A student draws a 3D model of a motor mount on screen, adds dimensions and exports the drawing so the shop can make it. She is using:','["computer-aided design (CAD) software to complete a design", "a calculator to add", "a game console to play", "a spreadsheet to type a letter"]'::jsonb,0,'CAD creates digital designs.','original'),
('127.813.d.1.A',4,'One advantage of designing a part in CAD instead of by hand is that the design can be:','["drawn only in pencil", "edited, measured and shared digitally with accuracy", "only printed once", "used only by its author"]'::jsonb,1,'Digital designs are editable and shareable.','original'),
('127.813.d.1.B',3,'Before building a bracket, a team applies a simulated load to its CAD model and sees a red zone where stress is highest. They are analyzing:','["a bank statement", "a weather map", "the results of product testing in a simulated modeling environment", "a sports table"]'::jsonb,2,'Simulation shows weak points.','original'),
('127.813.d.1.B',4,'The main benefit of simulated testing before fabrication is that it:','["adds to material cost", "skips design", "needs no software", "finds design weaknesses without wasting material"]'::jsonb,3,'Cheaper than breaking prototypes.','original'),
('127.813.d.1.C',3,'After approving a gear design, a student cuts and assembles a working model on a 3D printer and a mill to see whether it meshes. She is fabricating:','["a prototype of a mechanical part", "a classroom poster", "a cafeteria tray", "a final advertisement"]'::jsonb,0,'Prototypes test designs.','original'),
('127.813.d.1.C',4,'A prototype is built mainly to:','["replace all drawings", "test and improve a design before mass production", "be sold unchanged", "avoid planning"]'::jsonb,1,'Prototypes reveal flaws early.','original'),
('127.813.d.2.A',3,'A class uses software to simulate how robots, conveyors and machines move parts through a small plant before building the line. They are using:','["a drawing contest", "a voting booth", "computer-integrated manufacturing techniques to simulate a manufacturing process", "a cooking show"]'::jsonb,2,'CIM links computers and machines.','original'),
('127.813.d.2.A',4,'Computer-integrated manufacturing links design, machines and data so that:','["workers copy numbers by hand", "every step is separate", "no records are kept", "information flows automatically between steps"]'::jsonb,3,'CIM integrates operations.','original'),
('127.813.d.2.B',3,'A conveyor stops unexpectedly, and a technician uses a laptop connected to the controller to see which input never turned on. He is:','["troubleshooting programmable logic devices", "ordering lunch", "decorating the plant", "shipping boxes"]'::jsonb,0,'PLC troubleshooting finds faults.','original'),
('127.813.d.2.B',4,'A PLC, or programmable logic controller, is used to:','["compose music", "automate machines based on programmed logic and sensor inputs", "cook food", "print photos only"]'::jsonb,1,'PLCs control equipment.','original'),
('127.813.d.3.A',3,'A student compares limit switches, proximity sensors and relays to decide which would detect a box arriving on a conveyor. She is:','["researching school menus", "researching paint colors", "researching the use of control devices", "researching bus routes"]'::jsonb,2,'Control devices sense and switch.','original'),
('127.813.d.3.A',4,'A sensor that detects an object without touching it is a:','["paintbrush", "manual lever", "ruler", "proximity sensor"]'::jsonb,3,'Proximity sensors detect near objects.','original'),
('127.813.d.3.B',3,'A team wires a push button, a relay and a lamp so pressing the button turns the lamp on and keeps it latched until a stop button is pressed. They are:','["demonstrating the use of control devices", "writing a poem", "avoiding wiring", "drawing a map"]'::jsonb,0,'Hands-on control circuits.','original'),
('127.813.d.3.B',4,'In a simple control circuit, a stop button is commonly wired to:','["add power", "break the circuit and turn the device off", "increase voltage", "bypass the relay"]'::jsonb,1,'Stop interrupts the circuit.','original'),
('127.813.d.4.A',3,'A student sketches a simple cylinder in CAM software and sets cutting tools, speeds and feeds for a lathe. She is designing a product using:','["a drawing pad only", "a video editor", "computer-aided manufacturing software for production on a CNC lathe", "a spreadsheet only"]'::jsonb,2,'CAM prepares machine instructions.','original'),
('127.813.d.4.A',4,'A CNC lathe is best suited to making parts that are:','["thin fabrics", "flat sheets only", "liquid", "round, such as shafts and pins"]'::jsonb,3,'Lathes spin round parts.','original'),
('127.813.d.4.B',3,'Before cutting metal, a student runs the lathe program in a simulator to check that the tool path clears the chuck. She is producing a product on:','["a CNC lathe or a simulation", "a printer", "a blender", "a loom"]'::jsonb,0,'Simulation previews cutting.','original'),
('127.813.d.4.B',4,'Why run a lathe program in a simulator first?','["to avoid safety rules", "to find tool path errors before cutting real material", "to waste time", "to make parts bigger"]'::jsonb,1,'Simulate before cutting.','original'),
('127.813.d.4.C',3,'A team draws a pocket and a hole pattern in CAM software and generates toolpaths for a milling machine. They are designing a product for production on:','["a kiln", "a sewing machine", "a CNC mill", "a CNC lathe only"]'::jsonb,2,'Mills cut pockets and holes.','original'),
('127.813.d.4.C',4,'A CNC mill typically moves a rotating cutter along:','["one fixed line only", "no axes", "the ceiling", "several axes to remove material from a block"]'::jsonb,3,'Mills use multi-axis motion.','original'),
('127.813.d.4.D',3,'After checking the simulation, a student clamps an aluminum block, loads the program and cuts a nameplate on the mill. She is producing a product on:','["a CNC mill or a simulation", "a loom", "a sewing table", "a potter''s wheel"]'::jsonb,0,'Run the program on the mill.','original'),
('127.813.d.4.D',4,'Before starting a CNC mill program on a real part, the operator should always:','["remove the guard", "verify the work offset and tool setup", "skip the simulation", "turn off the stop button"]'::jsonb,1,'Verify setup.','original'),
('127.813.d.4.E',3,'Each team keeps a log of the plan, the run, the inspection results and the corrective changes for every project in a standard form. They are completing:','["menus", "playlists", "data sheets for plan, do, check and act forms and projects", "grocery lists"]'::jsonb,2,'PDCA documents improvement.','original'),
('127.813.d.4.E',4,'In the plan-do-check-act cycle, the ''check'' step is where a team:','["ships boxes", "starts a new product", "ignores the data", "measures results against the plan"]'::jsonb,3,'Check = compare to plan.','original'),
('127.813.d.5.A',3,'Students build a small lever, a gear train and a pulley and demonstrate how each changes force or speed. They are identifying, describing and demonstrating:','["mechanical devices", "fluid pumps only", "weather tools", "electronic chips"]'::jsonb,0,'Mechanical devices transmit motion.','original'),
('127.813.d.5.A',4,'A gear train with a small gear driving a large gear will:','["stop the shaft", "reduce speed and increase torque", "change nothing", "increase speed and reduce torque"]'::jsonb,1,'Gearing trades speed for torque.','original'),
('127.813.d.5.B',3,'A class uses a hand pump, tubing and a small cylinder filled with fluid to lift a load and explains why the fluid transmits force. They are demonstrating:','["magnetic toys", "wooden devices", "fluid devices", "optical devices"]'::jsonb,2,'Fluids transmit pressure.','original'),
('127.813.d.5.B',4,'A hydraulic jack works because a liquid in a closed system:','["compresses easily", "stops all force", "disappears", "transmits pressure equally in all directions"]'::jsonb,3,'Pascal''s principle.','original'),
('127.813.d.6.A',3,'A student labels a battery, a switch, a resistor and a motor on a schematic and describes what each does. She is identifying and describing:','["electrical devices", "mechanical levers only", "fluid devices", "optical devices only"]'::jsonb,0,'Electrical devices form circuits.','original'),
('127.813.d.6.A',4,'On a shop-floor wiring diagram, a technician sees a symbol for a device that can break the path so current stops flowing to a motor. That device is a:','["resistor", "switch", "battery", "capacitor"]'::jsonb,1,'A switch opens or closes the circuit path.','original'),
('127.813.d.6.B',3,'A team wires a motor to a battery through a switch, then adds a fuse and tests the circuit with a multimeter. They are demonstrating the use of:','["cooking tools", "gear trains only", "electrical devices", "fluid devices"]'::jsonb,2,'Hands-on circuits.','original'),
('127.813.d.6.B',4,'A multimeter set to volts is used to measure:','["the length of a wire", "the weight of a part", "the temperature of a room", "the electrical potential across two points"]'::jsonb,3,'Volts measure potential difference.','original'),
('127.813.d.6.C',3,'A class tests how a plastic part warps when baked at different temperatures and records its length each time. They are researching:','["the effects of heat energy and temperature on products", "the effects of lighting on color only", "the effects of music on mood", "the effects of weather on traffic"]'::jsonb,0,'Heat changes materials.','original'),
('127.813.d.6.C',4,'Most plastics will soften when:','["cooled slightly", "heated above their rated temperature", "painted", "labeled"]'::jsonb,1,'Thermal limits.','original'),
('127.813.d.7.A',3,'A quality technician learns that a certification from the International Organization for Standardization shows a plant follows agreed procedures for quality. She is researching:','["pop standards", "clothing sizes", "industrial standards such as ISO", "sports rules"]'::jsonb,2,'ISO standards promote consistency.','original'),
('127.813.d.7.A',4,'ISO standards help manufacturers by:','["reducing all costs", "making products identical in color", "removing inspection", "providing agreed quality and safety practices"]'::jsonb,3,'Common standards.','original'),
('127.813.d.7.B',3,'A chart sorts defect types from most to least frequent so the team can see that three causes produce most of the problems. This is a:','["Pareto chart", "pie of cookies", "map of roads", "calendar"]'::jsonb,0,'Pareto shows the vital few.','original'),
('127.813.d.7.B',4,'A Pareto chart is most useful for:','["listing every employee", "focusing on the few causes that create most defects", "selecting colors", "drawing parts"]'::jsonb,1,'80/20 rule.','original'),
('127.813.d.7.C',3,'A team plots the diameter of every fifth part on a control chart with upper and lower limits to see when the process drifts. They are applying:','["random picks", "gossip", "statistical process control", "guesswork"]'::jsonb,2,'SPC monitors stability.','original'),
('127.813.d.7.C',4,'A point that falls outside a control limit suggests:','["the product is free", "the process is perfect", "no action is needed", "the process may need investigation"]'::jsonb,3,'Out-of-control signal.','original'),
('127.814.d.1.A',3,'A shop planner uses ratios and unit conversions to decide how many pallets of parts can fit in a delivery truck and how much the load will cost. She is applying mathematics to problems arising in:','["everyday life, society and the workplace", "only a textbook example", "only a game board", "only a math contest"]'::jsonb,0,'Math solves real workplace problems.','original'),
('127.814.d.1.A',4,'A manufacturer needs 540 bolts for 90 identical assemblies. The bolts per assembly is:','["9", "6", "5", "50"]'::jsonb,1,'540 ÷ 90 = 6.','original'),
('127.814.d.1.B',3,'Told that a machine makes 120 parts per hour with 5 percent scrapped, a technician first lists what is known, plans how to find the good parts, solves, and then checks whether the answer makes sense. This is a:','["guess-and-skip method", "pick-the-longest-answer method", "problem-solving model of analyzing, planning, solving and justifying", "copy-from-a-friend method"]'::jsonb,2,'Analyze, plan, solve, check.','original'),
('127.814.d.1.B',4,'A machine makes 120 parts per hour with 5 percent scrapped. How many good parts per hour?','["115", "110", "119", "114"]'::jsonb,3,'5 percent of 120 is 6, and 120 - 6 = 114.','original'),
('127.814.d.1.C',3,'To check that a bracket''s hole spacing is 2.250 inches, a technician chooses a digital caliper over a tape measure and records the reading. She is selecting:','["tools, including technology, and techniques to solve the problem", "a random tool", "the least accurate tool", "no tool"]'::jsonb,0,'Tool choice affects accuracy.','original'),
('127.814.d.1.C',4,'To measure a part to the nearest thousandth of an inch, which tool is most appropriate?','["a protractor", "a micrometer or digital caliper", "a tape measure", "a yardstick"]'::jsonb,1,'Precision tools match tolerance.','original'),
('127.814.d.1.D',3,'A line lead explains to the crew, with a labeled diagram, why measuring from the same datum edge on every part prevents stacked errors. She is communicating:','["only a rumor", "only a final number", "mathematical ideas, reasoning and their implications using multiple representations", "only memorized rules"]'::jsonb,2,'Explain with words and diagrams.','original'),
('127.814.d.1.D',4,'Which representation best shows how a part''s dimensions relate to each other?','["a menu", "a color swatch", "a song lyric", "a labeled dimensioned drawing"]'::jsonb,3,'Drawings show dimensional relationships.','original'),
('127.814.d.1.E',3,'A quality team records weekly defect counts in a table, plots them on a graph and writes a one-line note about the trend. They are creating and using:','["representations to organize, record and communicate mathematical ideas", "random doodles", "unlabeled scrap notes", "only verbal guesses"]'::jsonb,0,'Tables and graphs record data.','original'),
('127.814.d.1.E',4,'A line graph of defects per week is useful because it shows:','["nothing about time", "how the number changes over time", "only the largest number", "only the smallest number"]'::jsonb,1,'Line graphs show trends.','original'),
('127.814.d.1.F',3,'A planner notices that doubling the batch size doubles the material needed and sees that cost per part falls when setup cost is spread over more parts. She is analyzing:','["unrelated facts", "only a picture", "mathematical relationships to connect and communicate mathematical ideas", "only the final price"]'::jsonb,2,'Relationships between quantities.','original'),
('127.814.d.1.F',4,'If a $200 setup cost is spread evenly across 100 parts, the setup cost per part is:','["$0.20", "$200", "$20", "$2"]'::jsonb,3,'200 ÷ 100 = 2.','original'),
('127.814.d.1.G',3,'A technician posts her tolerance calculation on the board, shows each step and explains why the measured part is within limits. She is displaying, explaining and justifying:','["mathematical ideas and arguments using precise mathematical language", "only a final answer", "only a drawing", "opinions without support"]'::jsonb,0,'Justify with steps and language.','original'),
('127.814.d.1.G',4,'A part must be 5.00 inches plus or minus 0.02 inches. Which measured length is acceptable?','["4.95 inches", "5.01 inches", "5.03 inches", "5.05 inches"]'::jsonb,1,'Range is 4.98 to 5.02.','original'),
('127.814.d.2.A',3,'A student models a robotic gripper in 3D software, adds dimensions and prepares drawings for fabrication. She is using:','["a text editor only", "presentation software only", "computer-aided design (CAD) software to complete a design", "a camera only"]'::jsonb,2,'CAD creates technical designs.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_112_v1'
from (values
('127.814.d.2.A',4,'A drawing exported from CAD for a machine shop should include:','["only a title", "only colors", "a decorative border only", "dimensions and tolerances"]'::jsonb,3,'Prints need sizes.','original'),
('127.814.d.2.B',3,'A team adjusts the wall thickness of a bracket in its model after the simulation shows deflection above the limit, then reruns the test. They are analyzing:','["the results of product testing in a simulated modeling environment", "a menu", "a score", "a schedule"]'::jsonb,0,'Simulation guides redesign.','original'),
('127.814.d.2.B',4,'If a simulation shows a part bending too much, the engineer should most likely:','["skip the test", "change the design to make it stiffer and rerun the test", "paint the part", "ignore the result"]'::jsonb,1,'Iterate on the design.','original'),
('127.814.d.2.C',3,'After the model passes simulation, a student machines a physical sample of a bearing housing to check fit on a shaft. She is:','["writing a report only", "printing a poster", "fabricating a prototype design of a mechanical part", "drawing a cartoon"]'::jsonb,2,'Prototype confirms fit.','original'),
('127.814.d.2.C',4,'Fabricating a prototype can reveal problems that:','["are always cosmetic", "cannot exist", "never matter", "did not show up in the computer model"]'::jsonb,3,'Real-world testing finds issues.','original'),
('127.814.d.2.D',3,'A class uses software to simulate a cell in which a robot loads a mill and an inspection station checks each part before packing. They are using:','["computer-integrated manufacturing techniques to simulate a manufacturing process", "a game console", "a music player", "a calendar"]'::jsonb,0,'CIM simulation previews flow.','original'),
('127.814.d.2.D',4,'Simulating a manufacturing cell before building it helps a company to:','["avoid all planning", "spot bottlenecks and plan layout cheaply", "skip safety", "remove workers"]'::jsonb,1,'Simulation finds problems early.','original'),
('127.814.d.3.A',3,'A team designs a sensor-and-relay system that stops a conveyor automatically when a box jams. They are developing:','["a poster", "a field trip", "solutions to use control devices", "a menu"]'::jsonb,2,'Control devices automate responses.','original'),
('127.814.d.3.A',4,'A system that stops a machine automatically when a sensor detects a jam is an example of:','["no control", "random control", "manual control only", "automatic control"]'::jsonb,3,'Sensors trigger actions.','original'),
('127.814.d.3.B',3,'A technician traces power to a PLC input module with a multimeter and finds that a sensor wire has come loose. He is:','["troubleshooting control devices such as programmable logic circuit devices", "ordering lunch", "painting a cabinet", "labeling boxes"]'::jsonb,0,'Trace signals to find faults.','original'),
('127.814.d.3.B',4,'The first step when troubleshooting a machine that will not start is usually to:','["hit the machine", "check for power and any tripped safety devices", "ignore the problem", "replace the whole machine"]'::jsonb,1,'Start with the simplest checks.','original'),
('127.814.d.4.A',3,'A student uses CAM software to define a part, select cutting tools and generate the code for a lathe. She is designing a project using:','["a drawing app only", "a calendar", "computer-aided manufacturing (CAM) software for a CNC lathe", "a spreadsheet only"]'::jsonb,2,'CAM generates CNC code.','original'),
('127.814.d.4.A',4,'The output of CAM software that tells a CNC machine what to do is called:','["spam", "a screenshot", "a calendar entry", "G-code"]'::jsonb,3,'G-code drives CNC machines.','original'),
('127.814.d.4.B',3,'A class checks a lathe program in a simulator, then turns a stepped aluminum shaft and measures each diameter. They are producing:','["a product on a CNC lathe or simulator", "a quilt", "a playlist", "a poem"]'::jsonb,0,'Simulate, then cut.','original'),
('127.814.d.4.B',4,'When a CNC lathe turns a stepped shaft, each step diameter is controlled by:','["the lighting", "the program''s X-axis tool positions", "the room temperature", "the operator''s mood"]'::jsonb,1,'X positions set diameters.','original'),
('127.814.d.4.C',3,'A team draws a flat plate with four holes and a slot in CAM software and defines the cutters and depths for a milling machine. They are designing a project using CAM for:','["a sewing machine", "a blender", "a CNC mill", "a copier"]'::jsonb,2,'Mills cut flat features.','original'),
('127.814.d.4.C',4,'For a CNC mill program, the tool''s depth of cut and feed rate are chosen so that:','["the cut is as deep as possible", "the tool spins slowly", "the part is ignored", "the cutter removes material without breaking or overheating"]'::jsonb,3,'Balanced cutting parameters.','original'),
('127.814.d.4.D',3,'A student clamps a block, sets the zero point and runs the mill program, first in simulation and then on the real machine. She is producing:','["a product on a CNC mill or simulator", "a mural", "a song", "a video"]'::jsonb,0,'Run on mill after simulating.','original'),
('127.814.d.4.D',4,'The ''work zero'' that a CNC mill operator sets on the stock defines:','["the color of the cutter", "the starting reference point for the program", "the weight of the part", "the end of the program"]'::jsonb,1,'Work offsets reference the program.','original'),
('127.814.d.4.E',3,'A class logs the plan, the actions taken, the inspection data and the improvements made on a shared form for each project. They are completing:','["a seating chart", "a game score", "data sheets for plan, do, check and act forms and projects", "a list of snacks"]'::jsonb,2,'PDCA forms record improvement.','original'),
('127.814.d.4.E',4,'The ''act'' step of plan-do-check-act is where a team:','["stops the project", "ignores the results", "deletes the data", "standardizes what worked or adjusts the plan"]'::jsonb,3,'Act = apply learning.','original'),
('127.814.d.5.A',3,'A student builds a belt-and-pulley system, a cam-and-follower and a gear set and tests how each moves a load. She is using:','["mechanical devices", "only optical devices", "only electrical devices", "only fluid devices"]'::jsonb,0,'Mechanical devices move loads.','original'),
('127.814.d.5.A',4,'A cam and follower mechanism converts rotating motion into:','["only heat", "linear back-and-forth motion", "only sound", "only light"]'::jsonb,1,'Cams create reciprocating motion.','original'),
('127.814.d.5.B',3,'A class connects an air compressor, a regulator and a small cylinder and uses a valve to extend and retract a rod. They are using:','["hydraulic jacks only", "magnets", "pneumatic devices", "optical sensors"]'::jsonb,2,'Pneumatics use compressed air.','original'),
('127.814.d.5.B',4,'Pneumatic systems are powered by:','["steam only", "sunlight", "compressed oil", "compressed air"]'::jsonb,3,'Air power.','original'),
('127.814.d.5.C',3,'A student connects a hand pump, hoses and a hydraulic cylinder and notices the cylinder lifts a heavy block with little hand effort. They are using:','["hydraulic devices", "pneumatic tools only", "wind turbines", "magnets"]'::jsonb,0,'Hydraulics multiply force.','original'),
('127.814.d.5.C',4,'Compared with pneumatic systems, hydraulic systems can usually exert:','["less force", "greater force because liquids are nearly incompressible", "the same weak force", "no force"]'::jsonb,1,'Hydraulic fluids resist compression.','original'),
('127.814.d.6.A',3,'A student wires a start/stop station, a contactor and an overload relay to run a small motor safely. She is using:','["only gears", "only hand tools", "electrical controls", "only fluid power"]'::jsonb,2,'Controls start and protect motors.','original'),
('127.814.d.6.A',4,'An overload relay in a motor circuit is used to:','["increase noise", "add speed", "reduce light", "protect the motor from drawing too much current"]'::jsonb,3,'Overload protection.','original'),
('127.814.d.6.B',3,'A team heats samples of three plastics to different temperatures and measures how much each expands and softens. They are analyzing:','["the effects of heat energy and temperature on products", "the effects of music on grades", "the effects of snacks on sleep", "the effects of paint on speed"]'::jsonb,0,'Heat affects properties.','original'),
('127.814.d.6.B',4,'Metals generally become more ductile and may lose strength when:','["painted", "heated to high temperatures", "cooled slightly", "wrapped in paper"]'::jsonb,1,'High heat alters properties.','original'),
('127.814.d.6.C',3,'A class studies how a plant''s heating, air conditioning and exhaust fans move air to keep fumes away from workers. They are developing an understanding of:','["musical rhythm", "sports scheduling", "ventilation, such as heating, air conditioning and exhaust", "map reading"]'::jsonb,2,'Ventilation controls air quality.','original'),
('127.814.d.6.C',4,'A welding shop installs exhaust hoods mainly to:','["raise fumes", "add decoration", "increase noise", "remove fumes and protect workers'' lungs"]'::jsonb,3,'Local exhaust removes hazards.','original'),
('127.814.d.7.A',3,'A line tech plots the average of five measured parts every hour against control limits and flags a downward trend in time to adjust the machine. She is applying:','["statistical process control", "a coin toss", "a hunch", "a rumor"]'::jsonb,0,'SPC tracks stability.','original'),
('127.814.d.7.A',4,'An upward or downward trend of several points in a row on a control chart usually indicates:','["a measurement of price", "the process may be shifting", "a perfect process", "no problem"]'::jsonb,1,'Trends signal drift.','original'),
('127.814.d.7.B',3,'A technician presses a diamond tip into a steel sample under a set load and measures the size of the dent to find how hard the metal is. She is determining:','["colors of different metals", "weights of different parts", "hardness values of different materials", "prices of different bolts"]'::jsonb,2,'Hardness tests use indentation.','original'),
('127.814.d.7.B',4,'A Rockwell hardness test measures a material''s:','["electrical resistance", "color", "density only", "resistance to indentation"]'::jsonb,3,'Rockwell = indentation hardness.','original'),
('127.814.d.7.C',3,'A bar chart counts defects by cause, and a cumulative line shows that two causes account for most defects. The team is analyzing:','["attribute and Pareto charts", "a season schedule", "a cookbook", "a seating chart"]'::jsonb,0,'Pareto charts rank causes.','original'),
('127.814.d.7.C',4,'On a Pareto chart, the bars are arranged:','["alphabetically", "from the most frequent cause to the least frequent", "from newest to oldest", "at random"]'::jsonb,1,'Descending order highlights priorities.','original'),
('127.814.d.8.A',3,'A team sketches a system in which a push button energizes a relay that opens a valve to move an air cylinder to stamp a part. They are designing a system with:','["only a gear set", "only a spring", "electrical controls and a pneumatic or hydraulic component", "only a pencil"]'::jsonb,2,'Electrical controls drive fluid power.','original'),
('127.814.d.8.A',4,'A solenoid valve in an air system is operated by:','["gravity only", "sound", "a hand crank only", "an electrical signal"]'::jsonb,3,'Solenoids convert signals to motion.','original'),
('127.814.d.8.B',3,'Following their schematic, students connect a control panel, a valve and an air cylinder and wire a start button to extend the rod. They are building:','["a system that incorporates electrical controls and a pneumatic or hydraulic component", "a quilt", "a paper airplane", "a birdhouse"]'::jsonb,0,'Build per the schematic.','original'),
('127.814.d.8.B',4,'Before powering up a newly built control system, the team should:','["cover the cylinder", "double-check wiring and air connections and clear the work area", "remove safety guards", "skip the check"]'::jsonb,1,'Verify before power-up.','original'),
('127.814.d.8.C',3,'The air cylinder does not extend when the start button is pressed, so the team checks the supply pressure, the valve coil and the wiring in turn. They are:','["buying a new machine", "guessing", "testing and troubleshooting the system", "abandoning the system"]'::jsonb,2,'Systematic troubleshooting.','original'),
('127.814.d.8.C',4,'When a system fails, a good troubleshooting approach is to:','["blame the operator", "change everything at once", "ignore the symptoms", "test one section at a time to isolate the fault"]'::jsonb,3,'Isolate the cause.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
